import { scene, light, camera, material } from 'candela';
import { jigScene } from 'jig-candela';
import { program } from 'jig-program';
const asm = jigScene(program, { autoFinish: true })
  .material("*", material.pbr().baseColor("#305ac9").roughness(0.45));
const v = asm.view('axo');
export default scene().add(asm)
  .add(light.sun().elevation(45).azimuth(135).illuminance(700))
  .add(light.env.gradient({ top: "#cbe4ff", bottom: "#243344", intensity: 700 }))
  .camera(camera.pinhole().at(v.at).lookAt(v.target));
